<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bestil {{$product->name}} · Nodexa</title><style>body{margin:0;background:#07111c;color:#f4f7fb;font-family:Inter,system-ui}.wrap{max-width:900px;margin:40px auto;padding:20px}.card{background:#0b1825;border:1px solid #1b3449;border-radius:12px;padding:26px}.tag{color:#3b8cff;font-size:11px;font-weight:800}.price{font-size:32px;font-weight:900;margin:18px 0}.features{display:grid;gap:9px;color:#aab6c7;margin:18px 0}.btn{border:0;background:#3b8cff;color:white;padding:14px 18px;border-radius:8px;font-weight:800;width:100%;cursor:pointer}.back{color:#91a0b5;text-decoration:none}.notice{background:#0f2132;padding:13px;border-radius:8px;color:#9cabbc;font-size:12px;margin:18px 0}.section{border-top:1px solid #1b3449;margin-top:22px;padding-top:20px}.section h3{margin:0 0 12px}.select,.input{box-sizing:border-box;width:100%;background:#0f2132;border:1px solid #29445d;color:#fff;padding:13px;border-radius:8px}.payments{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.pay{display:block;background:#0f2132;border:1px solid #29445d;border-radius:9px;padding:15px;cursor:pointer}.pay:has(input:checked){border-color:#3b8cff;box-shadow:0 0 0 1px #3b8cff}.pay input{margin-right:8px}.error{background:#351923;border:1px solid #6d2b3c;color:#ff9baa;padding:12px;border-radius:8px;margin:12px 0}.coupon{display:grid;grid-template-columns:1fr auto;gap:10px}.coupon span{background:#10283b;border:1px solid #29445d;padding:13px;border-radius:8px;color:#8eb5d6;font-weight:700}@media(max-width:650px){.payments{grid-template-columns:1fr}.coupon{grid-template-columns:1fr}}</style></head><body>@include('partials.announcement-banner')<div class="wrap"><a class="back" href="/client">← Client Area</a><div class="card" style="margin-top:18px"><span class="tag">{{$product->product_type==='vps'?'VPS HOSTING':'GAME HOSTING'}}</span><h1>{{$product->name}}</h1><p>{{$product->description}}</p><div class="price">{{number_format((float)$product->price,2,',','.')}} {{$product->currency}} <small style="font-size:13px;color:#91a0b5">/ måned</small></div><div class="features">@if($product->vcores)<span>✓ {{$product->vcores}} vCPU</span>@endif @if($product->memory_mb)<span>✓ {{number_format($product->memory_mb/1024,1,',','.')}} GB RAM</span>@endif @if($product->disk_mb)<span>✓ {{number_format($product->disk_mb/1024,1,',','.')}} GB disk</span>@endif @if($product->product_type==='vps')<span>✓ Fuld administrator/root-adgang</span><span>✓ VPS-styring i Nodexa</span>@endif</div>@if($errors->any())<div class="error">{{$errors->first()}}</div>@endif<form method="POST" action="/client/orders">@csrf<input type="hidden" name="product_id" value="{{$product->id}}">@if($product->product_type==='vps')<div class="section"><h3>1. Vælg operativsystem</h3>@if($osError)<div class="error">Kunne ikke hente OS-listen: {{$osError}}</div>@endif<select class="select" name="os_id" required><option value="">Vælg OS...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{old('os_id',(string)$product->default_os_id)==(string)$oid?'selected':''}}>{{$on}}</option>@endforeach</select></div>@endif<div class="section"><h3>{{$product->product_type==='vps'?'2.':'1.'}} Rabatkode</h3><div class="coupon"><input class="input" name="discount_code" value="{{old('discount_code')}}" placeholder="Indtast rabatkode"><span>Rabat beregnes sikkert ved bestilling</span></div></div><div class="section"><h3>{{$product->product_type==='vps'?'3.':'2.'}} Vælg betalingsmetode</h3>@if($gateways->isEmpty())<div class="error">Der er ingen aktive betalingsmetoder endnu. Kontakt support.</div>@else<div class="payments">@foreach($gateways as $g)<label class="pay"><input type="radio" name="payment_method" value="{{$g->gateway}}" {{old('payment_method')===$g->gateway?'checked':''}} required><strong>{{$g->name}}</strong><br><small style="color:#91a0b5">{{$g->test_mode?'Test / sandbox':'Sikker betaling'}}</small></label>@endforeach</div>@endif</div><div class="notice">VPS'en bliver først provisioneret efter en godkendt betaling. Rabatkoder valideres server-side og den endelige pris gemmes på ordre og faktura.</div><button class="btn" {{$gateways->isEmpty()?'disabled':''}}>Fortsæt til betaling →</button></form></div></div></body></html>